('0e90a698-f19f-5f8a-a64c-0bccf8659893','2fabe970-90d6-5ebc-a157-1f4ebee1b70b',34,'mcq',$q$Chọn nghĩa đúng của câu: 不过，这样更好。$q$,null,null,null,$q$["Trong vườn có rất nhiều cây.", "có điều, như vậy tốt hơn.", "Vui lòng bỏ rác vào thùng rác.", "Cuốn sách này rất dày."]$q$::jsonb,1,$q$不过$q$,3,null,null),
('ba401031-f741-57d0-a942-61b09b7bc03c','2fabe970-90d6-5ebc-a157-1f4ebee1b70b',35,'mcq',$q$Chọn nghĩa đúng của câu: 观众们都很满意。$q$,null,null,null,$q$["Ví dụ, táo và chuối đều là trái cây.", "Lúc đó tôi đang ở trường.", "Anh ấy gõ cửa rồi vào.", "Khán giả đều rất hài lòng."]$q$::jsonb,1,$q$观众$q$,3,null,null)
